INSERT INTO help_content (id, tenant_id, key, audience, locale, short_text, long_md, version, status)
VALUES (
  gen_random_uuid(),
  NULL,
  'candidate.shell.nav.mobile_menu',
  'candidate',
  'en',
  'Open the navigation menu. Jump to Certificates, Activity, or sign out.',
  $$## Candidate navigation menu

On a phone the top bar is too narrow to show the Certificates / Activity
links inline. Tap the small handle icon on the right of the top bar to
open a dropdown menu containing:

- **Certificates** — your earned certificates.
- **Activity** — your assessment history and rankings.
- **Sign out** — end your session.

The menu closes automatically when you pick an item, when you tap
outside it, or when you press Escape. On a laptop these links appear
inline in the top bar and the handle button is hidden.
$$,
